from sortedcontainers import SortedList
from typing import List

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)
        low = SortedList()
        high = SortedList()
        sum_low = 0
        sum_high = 0
        size_low = (x + 1) // 2  # ceil(x/2)

        def rebalance():
            nonlocal sum_low, sum_high
            while len(low) > size_low:
                val = low.pop()
                sum_low -= val
                high.add(val)
                sum_high += val
            while len(low) < size_low and high:
                val = high.pop(0)
                sum_high -= val
                low.add(val)
                sum_low += val

        def add(v):
            nonlocal sum_low, sum_high
            if not low or v <= low[-1]:
                low.add(v)
                sum_low += v
            else:
                high.add(v)
                sum_high += v
            rebalance()

        def remove(v):
            nonlocal sum_low, sum_high
            if v <= low[-1]:
                low.remove(v)
                sum_low -= v
            else:
                high.remove(v)
                sum_high -= v
            rebalance()

        # Initial window
        for i in range(x):
            add(nums[i])

        num_windows = n - x + 1
        costs = [0] * num_windows

        def get_cost():
            med = low[-1]
            return med * len(low) - sum_low + sum_high - med * len(high)

        costs[0] = get_cost()
        for i in range(x, n):
            remove(nums[i - x])
            add(nums[i])
            costs[i - x + 1] = get_cost()

        INF = float('inf')
        # dp[i][j] = min cost considering first i elements with j chosen subarrays
        dp = [[INF] * (k + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            dp[i][0] = 0

        for i in range(1, n + 1):
            for j in range(1, k + 1):
                dp[i][j] = dp[i - 1][j]
                if i >= x and dp[i - x][j - 1] < INF:
                    cand = dp[i - x][j - 1] + costs[i - x]
                    if cand < dp[i][j]:
                        dp[i][j] = cand

        return dp[n][k]
